{
  "id": 0,
  "knowledge": "Total Return Cost (TRC)",
  "description": "Aggregated monetary outlay incurred to handle a single return from transport to final disposition.",
  "definition": "The Total Return Cost is calculated as the sum of Shipping Fee ($S_f$), Restocking Fee ($R_f$), Relabeling Cost ($L_c$), Disposal Cost ($D_c$) and Repair Estimate ($R_e$): $$TRC = S_f + R_f + L_c + D_c + R_e$$."
}

{
  "id": 1,
  "knowledge": "Return Profit Impact (RPI)",
  "description": "Net financial impact of a return after accounting for cost and recovery value.",
  "definition": "$$RPI = R_v - TRC$$ where $R_v$ is Recovery Value and $TRC$ is Total Return Cost."
}

{
  "id": 10,
  "knowledge": "Shipping Fee",
  "description": "Cost charged by the logistics provider for transporting a returned item.",
  "definition": "A monetary amount reflecting transportation cost incurred for a single return shipment."
}

{
  "id": 11,
  "knowledge": "Restocking Fee",
  "description": "Service charge for reintegrating a returned item into inventory.",
  "definition": "Fee imposed to cover administrative and handling work required to make the item sellable again."
}

{
  "id": 13,
  "knowledge": "Disposal Cost",
  "description": "Fee incurred when discarding a returned item that cannot be resold or refurbished.",
  "definition": "Monetary cost of disposing the item through methods such as recycling, landfill, or hazardous-waste processing."
}

{
  "id": 14,
  "knowledge": "Repair Estimate",
  "description": "Projected expense required to bring a defective return back to sellable condition.",
  "definition": "Estimated sum of parts, labor and overhead needed for repair work, agreed before work commences."
}

